import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int x = sc.nextInt();
        int pos = x;
        int total = n;
        int cycles = total / 3;
        int rem = total % 3;
        // Reverse the remaining steps first
        for (int i = rem; i >= 1; i--) {
            if (i % 2 == 1) {
                // reverse odd step: swap left and middle
                if (pos == 0) pos = 1;
                else if (pos == 1) pos = 0;
            } else {
                // reverse even step: swap middle and right
                if (pos == 1) pos = 2;
                else if (pos == 2) pos = 1;
            }
        }
        // Reverse the cycles (each cycle is 3 steps: odd, even, odd)
        for (int i = 0; i < cycles; i++) {
            // reverse third step (odd): swap left and middle
            if (pos == 0) pos = 1;
            else if (pos == 1) pos = 0;
            // reverse second step (even): swap middle and right
            if (pos == 1) pos = 2;
            else if (pos == 2) pos = 1;
            // reverse first step (odd): swap left and middle
            if (pos == 0) pos = 1;
            else if (pos == 1) pos = 0;
        }
        System.out.println(pos);
    }
}
